import java.util.*;

class Solution {
    public int firstUniqueIndex(String s) {
        int[] cnt = new int[26];
        for (int i = 0; i < s.length(); i++) cnt[s.charAt(i) - 'a']++; // pass 1: count
        for (int i = 0; i < s.length(); i++) {
            if (cnt[s.charAt(i) - 'a'] == 1) return i; // pass 2: first letter seen once
        }
        return -1;
    }
}

python:
class Solution:
    def firstUniqueIndex(self, s: str) -> int:
        cnt = Counter(s)
        for i, c in enumerate(s):
            if cnt[c] == 1: return i
        return -1

